-- ============================================================
-- 圣遗物套装一览（首页模块 + 后台管理）
-- 覆盖原神主流 1~5 星圣遗物套装，含 2 件套 / 4 件套效果。
-- 本表由后台管理系统维护，若游戏版本更新后可直接在后台修正。
-- image 字段为前端 public 目录下的图标路径。
-- ============================================================
CREATE TABLE IF NOT EXISTS `t_artifact_set` (
  `id`            bigint       NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name`          varchar(50)  NOT NULL COMMENT '套装名',
  `rarity`        tinyint      NOT NULL DEFAULT 5 COMMENT '稀有度 3/4/5',
  `element`       varchar(20)  DEFAULT NULL COMMENT '主题标签: 元素 / 定位',
  `region`        varchar(30)  DEFAULT NULL COMMENT '主要获取区域',
  `two_piece`     varchar(500) DEFAULT NULL COMMENT '2 件套效果',
  `four_piece`    varchar(1000) DEFAULT NULL COMMENT '4 件套效果',
  `flavor`        varchar(200) DEFAULT NULL COMMENT '定位提示 / 备注',
  `image`         varchar(200) DEFAULT NULL COMMENT '图标路径',
  `theme_color`   varchar(20)  DEFAULT NULL COMMENT '卡片主题色',
  `sort_order`    int          NOT NULL DEFAULT 0 COMMENT '排序, 小的在前',
  `status`        tinyint      NOT NULL DEFAULT 1 COMMENT '状态: 1-显示 0-隐藏',
  `create_time`   datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time`   datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_artifact_name` (`name`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='圣遗物套装一览';

