  (`id`,`name`,`rarity`,`element`,`region`,`two_piece`,`four_piece`,`flavor`,`image`,`theme_color`,`sort_order`,`status`) VALUES
(1,'炽烈的炎之魔女',5,'火','蒙德','火元素伤害加成+15%','蒸发、融化反应造成的伤害+15%，超载、燃烧、烈绽放反应伤害+40%；施放元素战技后10秒内，2件套的效果提升50%，最多叠加3层','火系主C · 蒸发融化','/artifacts/xilie-yan-zhi-monv.png','#e0604a',1,1),
(2,'角斗士的终幕礼',5,'攻击','多地','攻击力+18%','装备者为单手剑、双手剑或长柄武器角色时，普通攻击造成的伤害+35%','普攻型主C','/artifacts/jiaodoushi-zhongmuli.png','#d9a45b',2,1),
(3,'流浪大地的乐团',5,'精通','多地','元素精通+80','装备者为法器或弓箭角色时，重击造成的伤害+35%','重击与反应型','/artifacts/liulang-dadi-yuetuan.png','#c58bd8',3,1),
(4,'昔日宗室之仪',5,'辅助','蒙德','元素爆发造成的伤害+20%','施放元素爆发后，队伍中所有角色攻击力+20%，持续12秒，该效果不可叠加','全队增伤辅助','/artifacts/xiri-zongshi-zhiyi.png','#6f8fe0',4,1),
(5,'被怜爱的少女',5,'治疗','蒙德','角色受到的治疗效果+15%','施放元素战技或元素爆发后的10秒内，队伍中所有角色受治疗效果+20%','治疗辅助','/artifacts/beilianai-shaonv.png','#7fd4a8',5,1),
(6,'翠绿之影',5,'风','蒙德','风元素伤害加成+15%','扩散反应造成的伤害+60%；根据扩散的元素类型，降低受影响的敌人对应元素抗性40%，持续10秒','风系减抗辅助','/artifacts/cuilv-zhiying.png','#4fc79b',6,1),
(7,'如雷的盛怒',5,'雷','蒙德','雷元素伤害加成+15%','超载、感电、超导、原激化反应伤害+40%，超激化反应伤害+20%；触发上述反应后元素战技冷却减少1秒，每0.8秒至多触发一次','雷系反应主C','/artifacts/rulei-de-shengnu.png','#a97ee0',7,1),
(8,'冰风迷途的勇士',5,'冰','龙脊雪山','冰元素伤害加成+15%','攻击处于冰元素影响下的敌人时暴击率+20%；若敌人处于冻结状态，暴击率额外+20%','永冻冰C','/artifacts/bingfeng-mitu-yongshi.png','#6fc7e8',8,1),
(9,'沉沦之心',5,'水','龙脊雪山','水元素伤害加成+15%','施放元素战技后的15秒内，普通攻击与重击造成的伤害+30%','水系站场主C','/artifacts/chenlun-zhixin.png','#4f9de0',9,1),
(10,'千岩牢固',5,'辅助','璃月','生命值+20%','元素战技命中敌人后，使队伍中附近所有角色攻击力+20%、护盾强效+30%，持续3秒；装备者处于后台时依然能触发该效果','生命辅助 · 护盾','/artifacts/qianyan-laogu.png','#d8b36a',10,1),
(11,'苍白之火',5,'物理','璃月','造成的物理伤害+25%','元素战技命中敌人后攻击力+9%，持续7秒，最多叠加2层；叠加2层时2件套的效果提升100%','物理主C','/artifacts/cangbai-zhihuo.png','#c9d3e0',11,1),
(12,'悠古的磐岩',5,'岩','璃月','岩元素伤害加成+15%','获得结晶反应产生的晶片时，队伍中所有角色获得该元素伤害加成+35%，持续10秒','结晶队辅助','/artifacts/yougu-de-panyan.png','#d9a95b',12,1),
(13,'逆飞的流星',5,'岩','璃月','护盾强效+35%','处于护盾庇护下时，额外获得40%普通攻击与重击伤害加成','护盾站场C','/artifacts/nifei-de-liuxing.png','#c0a4d8',13,1),
(14,'辰砂往生录',5,'攻击','璃月','攻击力+18%','施放元素爆发后产生持续16秒的「潜光」效果：攻击力+8%；角色生命值降低时攻击力进一步提升10%，至多4次','生命波动主C','/artifacts/chensha-wangshenglu.png','#e08a6a',14,1),
(15,'来歆余响',5,'攻击','璃月','攻击力+18%','普通攻击命中敌人时有36%概率触发「幽谷祝祀」，使该次普通攻击伤害提高攻击力的70%；未触发时下一次概率提升20%','普攻特化','/artifacts/laixin-yuxiang.png','#e0a86a',15,1),
(16,'绝缘之旗印',5,'充能','稻妻','元素充能效率+20%','元素爆发造成的伤害提升，提升量相当于元素充能效率超出100%部分的25%，至多通过该效果提升75%','爆发流副C','/artifacts/jueyuan-zhiqinyin.png','#8f7ee0',16,1),
(17,'追忆之注连',5,'攻击','稻妻','攻击力+18%','施放元素战技时若元素能量不低于15点，消耗15点元素能量，使接下来10秒内普通攻击、重击、下落攻击造成的伤害+50%','普攻重击主C','/artifacts/zhuiyi-zhulian.png','#d38fb0',17,1),
(18,'华馆梦醒形骸记',5,'防御','稻妻','防御力+30%','场上角色以岩元素攻击命中敌人后获得「问答」：防御力+6%、岩元素伤害加成+6%，持续15秒，最多4层；装备者处于后台时每3秒获得1层；满4层时该效果提升100%','防御型岩C','/artifacts/huaguan-mengxing.png','#b9a3d8',18,1),
(19,'海染砗磲',5,'治疗','稻妻','治疗效果+15%','装备者为队伍中角色恢复生命值时，将生成持续3秒的「海染泡沫」，记录治疗量；持续时间结束时对周围敌人造成相当于记录量90%的伤害','治疗转伤害','/artifacts/hairan-chequ.png','#6fc7c0',19,1),
(20,'饰金之梦',5,'精通','须弥','元素精通+80','触发元素反应后的8秒内，依据队伍中其他角色的元素类型使装备者获得强化：同元素角色使攻击力+14%，不同元素角色使元素精通+50；每类元素至多1层，至多3层','反应型主C','/artifacts/shijin-zhimeng.png','#d9b45b',20,1),
(21,'深林的记忆',5,'草','须弥','草元素伤害加成+15%','元素战技或元素爆发命中敌人后，使命中的敌人草元素抗性-30%，持续8秒；装备者处于后台时依然能触发该效果','草队减抗必备','/artifacts/shenlin-de-jiyi.png','#6fc46a',21,1),
(22,'乐园遗落之花',5,'精通','须弥','元素精通+80','装备者造成的绽放、超绽放、烈绽放反应伤害+40%；装备者触发上述反应后，该效果额外提升25%，最多叠加4层','绽放队核心','/artifacts/leyuan-yiluo-zhihua.png','#d98fb0',22,1),
(23,'沙上楼阁史话',5,'风','须弥','风元素伤害加成+15%','重击命中敌人后，该角色的普通攻击速度+10%，普通攻击、重击与下落攻击造成的伤害+40%，持续15秒','风系重击C','/artifacts/shashang-louge-shihua.png','#6fc7b0',23,1),
(24,'水仙之梦',5,'水','须弥','水元素伤害加成+15%','普通攻击、重击、下落攻击、元素战技或元素爆发命中敌人后获得1层「镜中水仙」，持续8秒；1/2/3层及以上时攻击力+7%/16%/25%，水元素伤害加成+4%/9%/15%','水系叠层主C','/artifacts/shuixian-zhimeng.png','#5fa8d8',24,1),
(25,'花海甘露之光',5,'生命','须弥','生命值+20%','元素战技与元素爆发造成的伤害+10%；装备者受到伤害后的5秒内，上述效果提升80%，最多叠加5层','生命型输出','/artifacts/huahai-ganlu-zhiguang.png','#d98fa0',25,1),
